<?php
declare(strict_types=1);
session_start();
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');
function respond(bool $ok,array $data=[],int $status=200):never{
 global $pdo,$uid;
 if($ok&&isset($pdo,$uid)&&($pdo instanceof PDO)){
   try{
     $s=$pdo->prepare('SELECT IF(id_usuario=?,id_usuario_alvo,id_usuario) blocked_id FROM social_relacoes_usuario WHERE st_bloqueado=1 AND (id_usuario=? OR id_usuario_alvo=?)');$s->execute([$uid,$uid,$uid]);$blocked=array_flip(array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN)));
     foreach(['posts','users','messages','comments','members','chats'] as $name){
       if(empty($data[$name])||!is_array($data[$name]))continue;
       $data[$name]=array_values(array_filter($data[$name],static function($item)use($blocked,$name){
         $other=(int)($item[$name==='chats'?'outro_usuario_id':'id_usuario']??0);return !$other||!isset($blocked[$other]);
       }));
     }
     if(isset($data['reports'])&&is_array($data['reports']))foreach($data['reports'] as &$report){
       if(($report['tipo_alvo']??'')!=='comunidade')continue;
       $q=$pdo->prepare('SELECT id_denuncia AS id,nm_criador AS nome_criador FROM mobile_denuncias_comunidade WHERE id_comunidade=? AND id_denunciante=?');$q->execute([(int)$report['id_alvo'],(int)$report['id_denunciante']]);$r=$q->fetch(PDO::FETCH_ASSOC);
       if(!$r)continue;
       $report['criador_nome']=$r['nome_criador'];
       $a=$pdo->prepare('SELECT id_anexo,nm_arquivo_original AS nome_original FROM mobile_denuncia_anexos WHERE id_denuncia=? ORDER BY id_anexo');$a->execute([(int)$r['id']]);$report['anexos']=$a->fetchAll(PDO::FETCH_ASSOC);
     }unset($report);
     if(isset($data['posts'])&&is_array($data['posts']))foreach($data['posts'] as &$row){
       $ac=array_column($pdo->query('SHOW COLUMNS FROM social_post_anexos')->fetchAll(PDO::FETCH_ASSOC),'Field');
       $path=in_array('ds_caminho',$ac,true)?'ds_caminho':'caminho';
       $name=in_array('nm_arquivo',$ac,true)?'nm_arquivo':'nome_arquivo';
       $mime=in_array('cd_tipo_mime',$ac,true)?'cd_tipo_mime':'mime_type';
       $order=in_array('nr_ordem',$ac,true)?'nr_ordem':'ordem';
       $t=$pdo->prepare("SELECT `$path` AS caminho,`$name` AS nome_arquivo,`$mime` AS mime_type FROM social_post_anexos WHERE id_post=? ORDER BY `$order`");$t->execute([(int)$row['id_post']]);$row['anexos']=$t->fetchAll(PDO::FETCH_ASSOC);
     }unset($row);
   }catch(Throwable $e){error_log('LibrasHub web filtro social: '.$e->getMessage());}
 }
 http_response_code($status);echo json_encode(['ok'=>$ok]+$data,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}
if(empty($_SESSION['usuario_id']))respond(false,['message'=>'Sessão expirada.'],401);
require_once __DIR__.'/../configs/config.php';require_once __DIR__.'/../configs/social_schema.php';require_once __DIR__.'/../configs/upload_helpers.php';ensureSocialSchema($pdo);$uid=(int)$_SESSION['usuario_id'];
if(empty($_SESSION['social_csrf']))$_SESSION['social_csrf']=bin2hex(random_bytes(24));
function input():array{if(str_contains($_SERVER['CONTENT_TYPE']??'','application/json'))return json_decode(file_get_contents('php://input'),true)?:[];return $_POST;}
function requireCsrf(array $d):void{if(!hash_equals((string)($_SESSION['social_csrf']??''),(string)($d['csrf']??'')))respond(false,['message'=>'Token de segurança inválido.'],403);}
function canCreate(PDO $pdo,int $uid):bool{if(strcasecmp((string)($_SESSION['usuario_tipo']??''),'Administrador')===0)return true;$s=$pdo->prepare("SELECT u.is_community_user OR EXISTS(SELECT 1 FROM usuario_roles ur JOIN roles r ON r.id_role=ur.id_role WHERE ur.id_usuario=u.id_usuario AND r.slug IN('comunitario','administrador')) FROM usuario u WHERE u.id_usuario=?");$s->execute([$uid]);return (bool)$s->fetchColumn();}
function isBlockedWeb(PDO $pdo,int $viewer,int $other):bool{
 if($viewer===$other)return false;
 $s=$pdo->prepare('SELECT 1 FROM social_relacoes_usuario WHERE st_bloqueado=1 AND ((id_usuario=? AND id_usuario_alvo=?) OR (id_usuario=? AND id_usuario_alvo=?)) LIMIT 1');
 $s->execute([$viewer,$other,$other,$viewer]);return (bool)$s->fetchColumn();
}
function requireWebContact(PDO $pdo,int $viewer,int $other):void{
 if(isBlockedWeb($pdo,$viewer,$other))respond(false,['message'=>'Usuário indisponível.'],403);
}
function member(PDO $pdo,int $chat,int $uid):void{$s=$pdo->prepare('SELECT 1 FROM social_chat_membros WHERE id_chat=? AND id_usuario=?');$s->execute([$chat,$uid]);if(!$s->fetchColumn())respond(false,['message'=>'Você não participa deste chat.'],403);$list=$pdo->prepare('SELECT id_usuario FROM social_chat_membros WHERE id_chat=? AND id_usuario<>?');$list->execute([$chat,$uid]);foreach($list->fetchAll(PDO::FETCH_COLUMN) as $other)requireWebContact($pdo,$uid,(int)$other);}
function uploadMedia(array $file,string $kind):array{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return [null,null,null];if(($file['error']??1)!==UPLOAD_ERR_OK)respond(false,['message'=>'Falha no upload.'],422);$max=$kind==='sticker'?2*1024*1024:8*1024*1024;if(($file['size']??0)>$max)respond(false,['message'=>$kind==='sticker'?'Figurinha deve ter até 2 MB.':'Imagem deve ter até 8 MB.'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=$kind==='sticker'?['image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif']:['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($allowed[$mime]))respond(false,['message'=>'Formato de mídia não permitido.'],422);$dir=dirname(__DIR__,2).'/static/uploads/social';if(!is_dir($dir)&&!mkdir($dir,0775,true))respond(false,['message'=>'Armazenamento indisponível.'],500);$name=bin2hex(random_bytes(18)).'.'.$allowed[$mime];if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))respond(false,['message'=>'Não foi possível salvar a mídia.'],500);return ['../static/uploads/social/'.$name,$mime,(int)$file['size']];}
function uploadPostMedia(array $file,bool $communityOnly=false):array{if(($file['error']??UPLOAD_ERR_NO_FILE)===UPLOAD_ERR_NO_FILE)return [null,null];if(($file['error']??1)!==UPLOAD_ERR_OK)respond(false,['message'=>'Falha no envio da mídia.'],422);$mime=(new finfo(FILEINFO_MIME_TYPE))->file($file['tmp_name']);$allowed=['image/jpeg'=>['jpg','imagem',8*1024*1024],'image/png'=>['png','imagem',8*1024*1024],'image/webp'=>['webp','imagem',8*1024*1024],'video/mp4'=>['mp4','video',40*1024*1024]];if(!$communityOnly){$allowed['image/gif']=['gif','imagem',8*1024*1024];$allowed['video/webm']=['webm','video',40*1024*1024];}if(!isset($allowed[$mime]))respond(false,['message'=>$communityOnly?'Use JPG, PNG, WebP ou MP4.':'Use JPG, PNG, WebP, GIF, MP4 ou WebM.'],422);[$ext,$type,$max]=$allowed[$mime];if(($file['size']??0)>$max)respond(false,['message'=>$type==='video'?'O vídeo deve ter até 40 MB.':'A imagem deve ter até 8 MB.'],422);$dir=dirname(__DIR__,2).'/static/uploads/social/feed';if(!is_dir($dir)&&!mkdir($dir,0775,true))respond(false,['message'=>'Armazenamento indisponível.'],500);$name=bin2hex(random_bytes(20)).'.'.$ext;if(!move_uploaded_file($file['tmp_name'],$dir.'/'.$name))respond(false,['message'=>'Não foi possível salvar a mídia.'],500);return ['../static/uploads/social/feed/'.$name,$type];}
function isAdministrator():bool{return strcasecmp(trim((string)($_SESSION['usuario_tipo']??'')),'Administrador')===0;}
function requireAdministrator():void{if(!isAdministrator())respond(false,['message'=>'Apenas administradores podem realizar esta ação.'],403);}
function activePunishment(PDO $pdo,int $user,string $type):?array{$s=$pdo->prepare("SELECT id_punicao,tipo,motivo,inicio_em,expira_em FROM usuario_punicoes WHERE id_usuario=? AND tipo=? AND revogada_em IS NULL AND expira_em>NOW() ORDER BY expira_em DESC LIMIT 1");$s->execute([$user,$type]);$row=$s->fetch();return $row?:null;}
function requirePermission(PDO $pdo,int $user,string $type):void{$punishment=activePunishment($pdo,$user,$type);if(!$punishment)return;$label=$type==='cadastrar_locais'?'cadastrar locais':'publicar ou comentar';respond(false,['message'=>'Sua permissão para '.$label.' está suspensa até '.date('d/m/Y H:i',strtotime((string)$punishment['expira_em'])).'. Motivo: '.(string)$punishment['motivo']],403);}
function managedCommunity(PDO $pdo,int $community,int $uid):array{$s=$pdo->prepare("SELECT c.* FROM social_comunidades c JOIN social_comunidade_membros m ON m.id_comunidade=c.id_comunidade AND m.id_usuario=? AND m.papel='dono' AND m.status='ativo' WHERE c.id_comunidade=? AND c.id_criador=?");$s->execute([$uid,$community,$uid]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Somente o dono pode gerenciar as informações da comunidade.'],403);return $row;}
function communityRole(PDO $pdo,int $community,int $uid):?string{$s=$pdo->prepare("SELECT papel FROM social_comunidade_membros WHERE id_comunidade=? AND id_usuario=? AND status='ativo' LIMIT 1");$s->execute([$community,$uid]);$role=$s->fetchColumn();return $role===false?null:(string)$role;}
function moderateCommunity(PDO $pdo,int $community,int $uid):string{$role=communityRole($pdo,$community,$uid);if(!in_array($role,['dono','moderador'],true))respond(false,['message'=>'Apenas o dono ou moderadores podem realizar esta ação.'],403);return $role;}
function readablePost(PDO $pdo,int $post,int $uid):array{$s=$pdo->prepare("SELECT p.id_post,p.id_usuario,p.id_comunidade,c.id_criador,c.privada,m.status FROM social_posts p LEFT JOIN social_comunidades c ON c.id_comunidade=p.id_comunidade LEFT JOIN social_comunidade_membros m ON m.id_comunidade=p.id_comunidade AND m.id_usuario=? WHERE p.id_post=?");$s->execute([$uid,$post]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Publicação não encontrada.'],404);requireWebContact($pdo,$uid,(int)$row['id_usuario']);if($row['id_comunidade']!==null&&(int)($row['privada']??0)===1&&($row['status']??'')!=='ativo'&&(int)($row['id_criador']??0)!==$uid&&!isAdministrator())respond(false,['message'=>'Entre na comunidade para interagir com esta publicação.'],403);return $row;}
function communityImage(array $file):?string{try{return storeImageUpload($file,'social/communities');}catch(RuntimeException $e){respond(false,['message'=>$e->getMessage()],422);}}
function cleanReportSource(string $source):?string{$source=trim(str_replace(["\r","\n"],'',$source));if($source===''||!str_starts_with($source,'/'))return null;return mb_substr($source,0,500);}
function reportSnapshot(PDO $pdo,string $type,int $target,int $uid):array{
    if($type==='post'){
        readablePost($pdo,$target,$uid);
        $s=$pdo->prepare("SELECT p.id_usuario,p.conteudo,p.midia_tipo,u.nm_usuario,c.nome comunidade_nome FROM social_posts p JOIN usuario u ON u.id_usuario=p.id_usuario LEFT JOIN social_comunidades c ON c.id_comunidade=p.id_comunidade WHERE p.id_post=?");$s->execute([$target]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Publicação não encontrada.'],404);
        $summary=trim((string)$row['conteudo']);if($summary==='')$summary=!empty($row['midia_tipo'])?'Publicação com mídia.':'Publicação sem texto.';
        return ['owner'=>(int)$row['id_usuario'],'title'=>'Publicação de '.(string)$row['nm_usuario'].(!empty($row['comunidade_nome'])?' em '.(string)$row['comunidade_nome']:''),'summary'=>mb_substr($summary,0,1000)];
    }
    if($type==='comentario'){
        $s=$pdo->prepare("SELECT c.id_usuario,c.id_post,c.conteudo,u.nm_usuario FROM social_post_comentarios c JOIN usuario u ON u.id_usuario=c.id_usuario WHERE c.id_comentario=?");$s->execute([$target]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Comentário não encontrado.'],404);readablePost($pdo,(int)$row['id_post'],$uid);
        return ['owner'=>(int)$row['id_usuario'],'title'=>'Comentário de '.(string)$row['nm_usuario'],'summary'=>mb_substr(trim((string)$row['conteudo']),0,1000)];
    }
    if($type==='usuario'){
        $s=$pdo->prepare('SELECT id_usuario,nm_usuario,social_handle FROM usuario WHERE id_usuario=?');$s->execute([$target]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Usuário não encontrado.'],404);
        $handle=trim((string)($row['social_handle']??''));return ['owner'=>(int)$row['id_usuario'],'title'=>'Perfil de '.(string)$row['nm_usuario'].($handle!==''?' (@'.$handle.')':''),'summary'=>'Perfil de usuário do LibrasHub.'];
    }
    if($type==='comunidade'){
        $s=$pdo->prepare("SELECT c.id_criador,c.nome,c.descricao,c.privada,m.status FROM social_comunidades c LEFT JOIN social_comunidade_membros m ON m.id_comunidade=c.id_comunidade AND m.id_usuario=? WHERE c.id_comunidade=?");$s->execute([$uid,$target]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Comunidade não encontrada.'],404);if((int)$row['privada']===1&&($row['status']??'')!=='ativo'&&(int)$row['id_criador']!==$uid&&!isAdministrator())respond(false,['message'=>'Você não tem acesso a esta comunidade.'],403);
        return ['owner'=>(int)$row['id_criador'],'title'=>'Comunidade '.(string)$row['nome'],'summary'=>mb_substr(trim((string)$row['descricao']),0,1000)];
    }
    if($type==='local'){
        $s=$pdo->prepare("SELECT id_usuario_criador,nome,descricao,cidade,uf FROM locais WHERE id_local=? AND status='aprovado'");$s->execute([$target]);$row=$s->fetch();if(!$row)respond(false,['message'=>'Local não encontrado.'],404);
        $summary=trim((string)$row['descricao']);if($summary==='')$summary='Local em '.(string)$row['cidade'].' - '.(string)$row['uf'].'.';
        return ['owner'=>(int)$row['id_usuario_criador'],'title'=>'Local '.(string)$row['nome'],'summary'=>mb_substr($summary,0,1000)];
    }
    respond(false,['message'=>'Tipo de denúncia inválido.'],422);
}
function reportTargetUrl(array $row):string{
    $id=(int)($row['id_alvo']??0);$type=(string)($row['tipo_alvo']??'');
    if($type==='usuario')return 'perfil.php?id='.$id;
    if($type==='comunidade')return 'chats.php?tab=communities&community='.$id;
    if($type==='local')return 'locais.php?local='.$id;
    $origin=trim((string)($row['origem_path']??''));if($origin!==''&&str_starts_with($origin,'/'))return $origin;
    return $type==='post'?'social.php#post-'.$id:'social.php';
}
$action=(string)($_GET['action']??$_POST['action']??'overview');
try{
if(in_array($action,['add_comment','post'],true))requirePermission($pdo,$uid,'publicar');
if($action==='feed_public'){$before=(int)($_GET['before']??0);$where='p.id_comunidade IS NULL';$params=[$uid];if($before>0){$where.=' AND p.id_post<?';$params[]=$before;}$s=$pdo->prepare("SELECT p.*,u.nm_usuario,u.foto_perfil,u.is_community_user,(SELECT COUNT(*) FROM social_post_curtidas l WHERE l.id_post=p.id_post) total_curtidas,(SELECT COUNT(*) FROM social_post_comentarios c WHERE c.id_post=p.id_post) total_comentarios,EXISTS(SELECT 1 FROM social_post_curtidas ml WHERE ml.id_post=p.id_post AND ml.id_usuario=?) curtiu FROM social_posts p JOIN usuario u ON u.id_usuario=p.id_usuario WHERE $where ORDER BY p.id_post DESC LIMIT 51");$s->execute($params);$posts=$s->fetchAll();$hasMore=count($posts)>50;if($hasMore)array_pop($posts);respond(true,['posts'=>$posts,'has_more'=>$hasMore]);}
if($action==='feed_unified'){
    $before=(int)($_GET['before']??0);
    $where="(
        (p.id_comunidade IS NULL AND (
            p.id_usuario=? OR
            EXISTS(SELECT 1 FROM social_seguidores sf WHERE sf.id_seguidor=? AND sf.id_seguido=p.id_usuario)
        ))
        OR
        (p.id_comunidade IS NOT NULL AND (
            EXISTS(SELECT 1 FROM social_comunidade_membros sm WHERE sm.id_comunidade=p.id_comunidade AND sm.id_usuario=? AND sm.status='ativo')
            OR
            (c.privada=0 AND (
                p.id_usuario=?
                OR EXISTS(SELECT 1 FROM social_seguidores sf2 WHERE sf2.id_seguidor=? AND sf2.id_seguido=p.id_usuario)
            ))
        ))
    )";
    $params=[$uid,$uid,$uid,$uid,$uid,$uid];
    if($before>0){$where.=' AND p.id_post<?';$params[]=$before;}
    $s=$pdo->prepare("SELECT p.*,u.nm_usuario,u.foto_perfil,u.is_community_user,c.nome comunidade_nome,am.papel papel_comunidade,
        (SELECT COUNT(*) FROM social_post_curtidas l WHERE l.id_post=p.id_post) total_curtidas,
        (SELECT COUNT(*) FROM social_post_comentarios pc WHERE pc.id_post=p.id_post) total_comentarios,
        EXISTS(SELECT 1 FROM social_post_curtidas ml WHERE ml.id_post=p.id_post AND ml.id_usuario=?) curtiu
        FROM social_posts p
        JOIN usuario u ON u.id_usuario=p.id_usuario
        LEFT JOIN social_comunidades c ON c.id_comunidade=p.id_comunidade
        LEFT JOIN social_comunidade_membros am ON am.id_comunidade=p.id_comunidade AND am.id_usuario=p.id_usuario AND am.status='ativo'
        WHERE $where
        ORDER BY p.id_post DESC LIMIT 51");
    $s->execute($params);
    $posts=$s->fetchAll();$hasMore=count($posts)>50;if($hasMore)array_pop($posts);
    respond(true,['posts'=>$posts,'has_more'=>$hasMore]);
}
if($action==='create_public_post'){$d=$_POST;requireCsrf($d);requirePermission($pdo,$uid,'publicar');$text=mb_substr(trim((string)($d['text']??'')),0,4000);[$url,$type]=uploadPostMedia($_FILES['media']??[]);if($text===''&&!$url)respond(false,['message'=>'Escreva algo ou selecione uma foto ou vídeo.'],422);$s=$pdo->prepare('INSERT INTO social_posts(id_comunidade,id_usuario,conteudo,midia_url,midia_tipo) VALUES(NULL,?,?,?,?)');$s->execute([$uid,$text,$url,$type]);respond(true,['id'=>(int)$pdo->lastInsertId(),'message'=>'Publicação criada.']);}
if($action==='edit_post'){$d=input();requireCsrf($d);$post=(int)($d['post']??0);$text=mb_substr(trim((string)($d['text']??'')),0,4000);$s=$pdo->prepare('SELECT midia_url FROM social_posts WHERE id_post=? AND id_usuario=?');$s->execute([$post,$uid]);$media=$s->fetchColumn();if($media===false)respond(false,['message'=>'Publicação não encontrada ou sem permissão para editar.'],404);if($text===''&&empty($media))respond(false,['message'=>'O texto não pode ficar vazio.'],422);$pdo->prepare('UPDATE social_posts SET conteudo=?,editado_em=CURRENT_TIMESTAMP WHERE id_post=? AND id_usuario=?')->execute([$text,$post,$uid]);respond(true,['text'=>$text,'message'=>'Publicação atualizada.']);}
if($action==='toggle_like'){$d=input();requireCsrf($d);$post=(int)($d['post']??0);readablePost($pdo,$post,$uid);$exists=$pdo->prepare('SELECT 1 FROM social_post_curtidas WHERE id_post=? AND id_usuario=?');$exists->execute([$post,$uid]);if($exists->fetchColumn()){$pdo->prepare('DELETE FROM social_post_curtidas WHERE id_post=? AND id_usuario=?')->execute([$post,$uid]);$liked=false;}else{$pdo->prepare('INSERT IGNORE INTO social_post_curtidas(id_post,id_usuario) VALUES(?,?)')->execute([$post,$uid]);$liked=true;}$count=$pdo->prepare('SELECT COUNT(*) FROM social_post_curtidas WHERE id_post=?');$count->execute([$post]);respond(true,['liked'=>$liked,'count'=>(int)$count->fetchColumn()]);}
if($action==='comments'){$post=(int)($_GET['post']??0);readablePost($pdo,$post,$uid);$s=$pdo->prepare('SELECT c.id_comentario,c.id_comentario_pai,c.conteudo,c.criado_em,u.id_usuario,u.nm_usuario,u.foto_perfil,u.is_community_user,cm.papel papel_comunidade,(SELECT COUNT(*) FROM social_comentario_curtidas cl WHERE cl.id_comentario=c.id_comentario) total_curtidas,EXISTS(SELECT 1 FROM social_comentario_curtidas ml WHERE ml.id_comentario=c.id_comentario AND ml.id_usuario=?) curtiu FROM social_post_comentarios c JOIN usuario u ON u.id_usuario=c.id_usuario JOIN social_posts p ON p.id_post=c.id_post LEFT JOIN social_comunidade_membros cm ON cm.id_comunidade=p.id_comunidade AND cm.id_usuario=c.id_usuario AND cm.status=\'ativo\' WHERE c.id_post=? ORDER BY c.id_comentario LIMIT 300');$s->execute([$uid,$post]);respond(true,['comments'=>$s->fetchAll()]);}
