    $pdo->prepare('UPDATE usuario_punicoes SET revogada_em=NOW() WHERE id_usuario=? AND tipo=? AND revogada_em IS NULL AND expira_em>NOW()')->execute([$user,$type]);respond(true,['message'=>'Permissão restaurada.']);
}
if($action==='admin_delete_user'){
    requireAdministrator();$d=input();requireCsrf($d);$user=(int)($d['user']??0);if($user<1||$user===$uid)respond(false,['message'=>'Você não pode excluir a própria conta administrativa.'],422);
    $s=$pdo->prepare('DELETE FROM usuario WHERE id_usuario=?');$s->execute([$user]);if(!$s->rowCount())respond(false,['message'=>'Usuário não encontrado.'],404);respond(true,['message'=>'Conta excluída permanentemente.']);
}
if($action==='places'){$s=$pdo->query("SELECT id_local,nome,tipo,descricao,logradouro,numero,bairro,cidade,uf,cep,latitude,longitude,imagem_principal,acessibilidades FROM locais WHERE status='aprovado' ORDER BY nome");respond(true,['places'=>$s->fetchAll()]);}
if($action==='moderation_reports'){
    if(!isAdministrator())respond(false,['message'=>'Apenas administradores podem acessar as denúncias.'],403);
    $filter=(string)($_GET['status']??'pendente');$allowed=['pendente','analise','resolvida','arquivada','todas'];if(!in_array($filter,$allowed,true))$filter='pendente';
    $counts=['pendente'=>0,'analise'=>0,'resolvida'=>0,'arquivada'=>0];$rows=$pdo->query("SELECT status,COUNT(*) total FROM social_denuncias GROUP BY status")->fetchAll();foreach($rows as $countRow)$counts[(string)$countRow['status']]=(int)$countRow['total'];
    $sql="SELECT d.*,r.nm_usuario denunciante_nome,m.nm_usuario moderador_nome FROM social_denuncias d JOIN usuario r ON r.id_usuario=d.id_denunciante LEFT JOIN usuario m ON m.id_usuario=d.id_moderador";$params=[];if($filter!=='todas'){$sql.=' WHERE d.status=?';$params[]=$filter;}$sql.=' ORDER BY CASE d.status WHEN \'pendente\' THEN 1 WHEN \'analise\' THEN 2 WHEN \'resolvida\' THEN 3 ELSE 4 END,d.atualizado_em DESC';$s=$pdo->prepare($sql);$s->execute($params);$reports=$s->fetchAll();
    foreach($reports as &$report){$report['target_url']=reportTargetUrl($report);$report['id_denuncia']=(int)$report['id_denuncia'];$report['id_alvo']=(int)$report['id_alvo'];}unset($report);respond(true,['reports'=>$reports,'counts'=>$counts,'filter'=>$filter]);
}
if($action==='moderation_report_update'){
    if(!isAdministrator())respond(false,['message'=>'Apenas administradores podem moderar denúncias.'],403);$d=input();requireCsrf($d);$id=(int)($d['report']??0);$status=(string)($d['status']??'');$resolution=mb_substr(trim((string)($d['resolution']??'')),0,1000);$allowed=['pendente','analise','resolvida','arquivada'];if($id<1||!in_array($status,$allowed,true))respond(false,['message'=>'Atualização de moderação inválida.'],422);if(in_array($status,['resolvida','arquivada'],true)&&mb_strlen($resolution)<5)respond(false,['message'=>'Informe uma observação de resolução com pelo menos 5 caracteres.'],422);
    $resolved=in_array($status,['resolvida','arquivada'],true);$s=$pdo->prepare("UPDATE social_denuncias SET status=?,id_moderador=?,resolucao=?,resolvido_em=".($resolved?'CURRENT_TIMESTAMP':'NULL').",atualizado_em=CURRENT_TIMESTAMP WHERE id_denuncia=?");$s->execute([$status,$uid,$resolution!==''?$resolution:null,$id]);if(!$s->rowCount()){$check=$pdo->prepare('SELECT 1 FROM social_denuncias WHERE id_denuncia=?');$check->execute([$id]);if(!$check->fetchColumn())respond(false,['message'=>'Denúncia não encontrada.'],404);}respond(true,['message'=>'Denúncia atualizada.','status'=>$status]);
}
if($action==='report'){
    $d=input();requireCsrf($d);$type=(string)($d['type']??'');$target=(int)($d['id']??0);$reason=(string)($d['reason']??'');$details=mb_substr(trim((string)($d['details']??'')),0,1000);$source=cleanReportSource((string)($d['source']??''));$allowedTypes=['post','comentario','usuario','comunidade','local'];$allowedReasons=['spam','odio','assedio','violencia','conteudo_improprio','outro'];if(!in_array($type,$allowedTypes,true)||$target<1)respond(false,['message'=>'Conteúdo inválido para denúncia.'],422);if(!in_array($reason,$allowedReasons,true))respond(false,['message'=>'Selecione um motivo válido.'],422);if($reason==='outro'&&mb_strlen($details)<10)respond(false,['message'=>'Explique o motivo da denúncia em pelo menos 10 caracteres.'],422);
    $snapshot=reportSnapshot($pdo,$type,$target,$uid);if((int)$snapshot['owner']===$uid)respond(false,['message'=>'Você não pode denunciar seu próprio conteúdo ou perfil.'],422);
    $existing=$pdo->prepare('SELECT id_denuncia,status FROM social_denuncias WHERE id_denunciante=? AND tipo_alvo=? AND id_alvo=?');$existing->execute([$uid,$type,$target]);$previous=$existing->fetch();
    $s=$pdo->prepare("INSERT INTO social_denuncias(id_denunciante,tipo_alvo,id_alvo,motivo,detalhes,alvo_titulo,alvo_resumo,origem_path,status,id_moderador,resolucao,resolvido_em) VALUES(?,?,?,?,?,?,?,?,'pendente',NULL,NULL,NULL) ON DUPLICATE KEY UPDATE motivo=VALUES(motivo),detalhes=VALUES(detalhes),alvo_titulo=VALUES(alvo_titulo),alvo_resumo=VALUES(alvo_resumo),origem_path=COALESCE(VALUES(origem_path),origem_path),status='pendente',id_moderador=NULL,resolucao=NULL,resolvido_em=NULL,atualizado_em=CURRENT_TIMESTAMP");$s->execute([$uid,$type,$target,$reason,$details!==''?$details:null,$snapshot['title'],$snapshot['summary'],$source]);
    respond(true,['message'=>$previous?'Denúncia atualizada e reenviada para análise.':'Denúncia enviada para a moderação.','updated'=>(bool)$previous]);
}
respond(false,['message'=>'Ação inválida.'],400);
}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$diagnostico=bin2hex(random_bytes(4));error_log('[LibrasHub Web Social]['.($action??'desconhecida').']['.$diagnostico.'] '.$e->getMessage());respond(false,['message'=>'Módulo Social indisponível. Código de diagnóstico: '.$diagnostico],500);}
